"""Class implementations generated by backend: dataclass and pydantic."""

import ast
from pathlib import Path

import pytest

from pyleecan.classes_common.class_lookup import find_module_paths
from pyleecan.Classes_pydantic._import import LOOKUP as PYDANTIC_LOOKUP
from pyleecan.Classes_pydantic._pyleecan_model import PyleecanModel
from pyleecan.definitions import DOC_DIR, MAIN_DIR
from pyleecan.Generator.ClassGenerator.New.class_generator import (
    BACKENDS,
    _keyword_geometry_calls,
    _with_field_alias,
    backend_package,
    relocate_class_imports,
)
from pyleecan.Generator.read_fct import read_all

GEN_DICT = read_all(DOC_DIR)


def test_backend_package():
    assert backend_package("dataclass") == "Classes_new"
    assert backend_package("pydantic") == "Classes_pydantic"
    with pytest.raises(ValueError):
        backend_package("attrs")


def test_relocate_to_backend_package():
    source = (
        "from pyleecan.Classes_new.arc_1 import Arc1\n"
        "from pyleecan.Classes_new._import import import_class\n"
        "from pyleecan.Classes_new._pyleecan_model import PyleecanModel\n"
        "from pyleecan.Classes_new._error import CheckTypeError\n"
        "from pyleecan.Classes_new._swat_em import datamodel\n"
    )
    expected = (
        "from pyleecan.Classes_pydantic.geometry.arc_1 import Arc1\n"
        "from pyleecan.Classes_pydantic._import import import_class\n"
        "from pyleecan.Classes_pydantic._pyleecan_model import PyleecanModel\n"
        "from pyleecan.classes_common.errors import CheckTypeError\n"
        "from pyleecan.Classes_new._swat_em import datamodel\n"  # vendored: kept
    )
    assert (
        relocate_class_imports(
            source,
            "pyleecan",
            "Classes_new",
            {"arc_1": "geometry.arc_1"},
            "Classes_pydantic",
        )
        == expected
    )


@pytest.mark.parametrize(
    "default, expected",
    [
        ("None", "Field(default=None, alias='_x')"),
        ("Field(default_factory=dict)", "Field(alias='_x', default_factory=dict)"),
        ("Field()", "Field(alias='_x')"),
    ],
)
def test_with_field_alias(default, expected):
    assert _with_field_alias(default, "Field", "_x") == expected


def test_same_class_tree():
    """Both backends hold the same class modules in the same sub-packages"""
    root = Path(MAIN_DIR)
    assert find_module_paths(root / BACKENDS["dataclass"]) == find_module_paths(
        root / BACKENDS["pydantic"]
    )


@pytest.mark.parametrize("class_name", sorted(GEN_DICT))
def test_pydantic_class(class_name):
    """Every pydantic class builds its schema and a default object"""
    cls = PYDANTIC_LOOKUP.import_class(class_name)
    assert issubclass(cls, PyleecanModel)
    assert cls.__module__.startswith("pyleecan.Classes_pydantic.")
    obj = cls()
    assert type(obj).from_dict(obj.as_dict()) == obj


def test_pydantic_legacy_field_name():
    """A legacy field starting with "_" keeps its name for methods and files"""
    from pyleecan.Classes_pydantic.elmer.section import Section

    section = Section(section="Body")
    section["a"] = 1  # methods use self._statements
    assert section.statements == section._statements == {"a": 1}
    data = section.as_dict()
    assert data["_statements"] == {"a": 1} and "statements" not in data
    assert Section.from_dict(data) == section
    assert Section(_statements={"b": 2}).statements == {"b": 2}


def test_keyword_calls_for_every_class():
    """Constructor calls of every generated class use keyword arguments"""
    source = (
        "from pyleecan.Classes_new.lam_slot_wind import LamSlotWind\n"
        "from pyleecan.Classes_new.segment import Segment\n"
        "lam = LamSlotWind(0.1, 0.2)\n"
        "line = Segment(0, 1)\n"
    )
    result = _keyword_geometry_calls(source, "pyleecan", GEN_DICT)
    calls = [node for node in ast.walk(ast.parse(result)) if isinstance(node, ast.Call)]
    assert len(calls) == 2
    assert all(not call.args and call.keywords for call in calls)
